#!/usr/bin/env node
// LIVE テスト用の小さなサンプルリポジトリを作る（node-pnpm プロファイル対応）。
// 使い方: node tests/fixtures/make-sample-repo.mjs <dir>
import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const dir = resolve(process.argv.slice(2).find((a) => !a.startsWith('--')) ?? 'sample-repo');
mkdirSync(join(dir, 'src'), { recursive: true });
mkdirSync(join(dir, 'test'), { recursive: true });
mkdirSync(join(dir, 'scripts'), { recursive: true });
mkdirSync(join(dir, 'docs'), { recursive: true });
writeFileSync(join(dir, 'package.json'), JSON.stringify({
  name: 'sample-app', version: '0.0.1', private: true, type: 'module',
  scripts: { typecheck: 'tsc -p tsconfig.json --noEmit', lint: 'eslint src test', 'test:run': 'vitest run', 'docs:api': 'node scripts/gen-api-docs.mjs' },
  devDependencies: { typescript: '~5.9.3', vitest: '^4.1.12', eslint: '^9.39.0', '@eslint/js': '^9.39.0', 'typescript-eslint': '^8.72.1', '@types/node': '^22.20.5' }
}, null, 2));
writeFileSync(join(dir, 'tsconfig.json'), JSON.stringify({ compilerOptions: { target: 'ES2022', module: 'NodeNext', moduleResolution: 'NodeNext', strict: true, noEmit: true, types: ['node'] }, include: ['src', 'test'] }, null, 2));
// --strict-lint: no-console とテンプレートリテラル禁止を error にする（Phase 2「検証失敗 → 修正」シナリオ用）
const strictLint = process.argv.includes('--strict-lint');
// --pm npm|yarn|pnpm: lockfile を作るパッケージマネージャ（v0.3、D-44。既定は pnpm）
const pmArgIndex = process.argv.indexOf('--pm');
const pm = pmArgIndex >= 0 ? process.argv[pmArgIndex + 1] : 'pnpm';
if (!['pnpm', 'npm', 'yarn'].includes(pm)) throw new Error(`--pm は pnpm | npm | yarn: ${pm}`);
writeFileSync(
  join(dir, 'eslint.config.js'),
  strictLint
    ? "import js from '@eslint/js';\nimport tseslint from 'typescript-eslint';\nexport default tseslint.config(js.configs.recommended, ...tseslint.configs.recommended, { rules: { 'no-console': 'error', 'no-restricted-syntax': ['error', { selector: 'TemplateLiteral', message: 'プロジェクト規約: テンプレートリテラルは使わず文字列連結を使う' }] } });\n"
    : "import js from '@eslint/js';\nimport tseslint from 'typescript-eslint';\nexport default tseslint.config(js.configs.recommended, ...tseslint.configs.recommended);\n"
);
writeFileSync(join(dir, 'src', 'greet.ts'), strictLint ? "export function greet(name: string): string {\n  return 'Hello, ' + name + '!';\n}\n" : "export function greet(name: string): string {\n  return `Hello, ${name}!`;\n}\n");
writeFileSync(join(dir, 'test', 'greet.test.ts'), "import { expect, it } from 'vitest';\nimport { greet } from '../src/greet.js';\n\nit('greets', () => {\n  expect(greet('world')).toBe('Hello, world!');\n});\n");
writeFileSync(join(dir, 'README.md'), '# sample-app\n\nA tiny TypeScript library used as the LIVE test target.\n\nAPI docs: docs/API.md is generated by `pnpm run docs:api`; do not edit it by hand.\n');
// 生成物（v0.2.1 D-41 の実機検証用）: src/*.ts の export function 一覧を docs/API.md に生成する。入力はすべてコミット済みなのでサンドボックスで再現できる
writeFileSync(
  join(dir, 'scripts', 'gen-api-docs.mjs'),
  [
    "import { readdirSync, readFileSync, writeFileSync } from 'node:fs';",
    "const lines = ['<!-- 自動生成: scripts/gen-api-docs.mjs（pnpm run docs:api）。手で編集しない -->', '', '# API', ''];",
    "for (const f of readdirSync('src').filter((x) => x.endsWith('.ts')).sort()) {",
    "  const src = readFileSync('src/' + f, 'utf8');",
    "  for (const m of src.matchAll(/export function ([A-Za-z0-9_]+)\\(([^)]*)\\)(?::\\s*([^{]+))?/g)) lines.push('- `' + m[1] + '(' + m[2].trim() + ')' + (m[3] ? ': ' + m[3].trim() : '') + '` — src/' + f);",
    "}",
    "writeFileSync('docs/API.md', lines.join('\\n') + '\\n');",
    ''
  ].join('\n')
);
writeFileSync(join(dir, 'docs', 'API.md'), '<!-- 自動生成: scripts/gen-api-docs.mjs（pnpm run docs:api）。手で編集しない -->\n\n# API\n\n- `greet(name: string): string` — src/greet.ts\n');
writeFileSync(join(dir, '.gitignore'), 'node_modules/\n');
// Windows の pnpm は .cmd シムなので shell 経由で起動する（テスト用フィクスチャ。引数は固定）
// corepack / yarn 1.22 が packageManager を自動で書き込まないようにする（ホストの npm_config_user_agent を拾って壊れた値になる）
const env = { ...process.env, COREPACK_ENABLE_AUTO_PIN: '0', COREPACK_ENABLE_STRICT: '0', YARN_ENABLE_GLOBAL_CACHE: '1' };
delete env.npm_config_user_agent;
const run = (cmd, args) => execFileSync(cmd, args, { cwd: dir, stdio: 'inherit', shell: cmd.endsWith('.cmd'), env });
const win = process.platform === 'win32';
if (pm === 'pnpm') run(win ? 'pnpm.cmd' : 'pnpm', ['install', '--lockfile-only']);
else if (pm === 'npm') run(win ? 'npm.cmd' : 'npm', ['install', '--package-lock-only', '--ignore-scripts', '--no-audit', '--no-fund']);
else {
  // yarn 1.22.22 は yarn.lock が見つかるまで親ディレクトリを辿り、このリポジトリの package.json（packageManager: pnpm）を拾って拒否する。
  // 空の yarn.lock を先に置いてサンプルをプロジェクトルートにする（install が正しい内容で上書きする）
  writeFileSync(join(dir, 'yarn.lock'), '');
  run(win ? 'npx.cmd' : 'npx', ['-y', 'yarn@1.22.22', 'install', '--ignore-scripts', '--non-interactive']); // yarn 1 は lockfile だけの生成ができないため node_modules も作る（.gitignore 済み）
}
// 念のため packageManager を取り除く（サンドボックスは lockfile で判定する）
const pkgPath = join(dir, 'package.json');
const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
delete pkg.packageManager;
writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
run('git', ['init', '-q', '-b', 'main']);
run('git', ['add', '-A']);
run('git', ['-c', 'user.email=sample@example.com', '-c', 'user.name=sample', 'commit', '-q', '-m', 'init']);
console.log(`sample repo created at ${dir}`);
